import{_ as e,o as r,c as t,a5 as o}from"./chunks/framework.D4tbZp_W.js";const p=JSON.parse('{"title":"如何做主题阅读","description":"","frontmatter":{},"headers":[],"relativePath":"reading/how-to-read.md","filePath":"reading/how-to-read.md","lastUpdated":1786328197000}'),d={name:"reading/how-to-read.md"};function n(i,a,h,l,s,c){return r(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="如何做主题阅读" tabindex="-1">如何做主题阅读 <a class="header-anchor" href="#如何做主题阅读" aria-label="Permalink to “如何做主题阅读”">​</a></h1><p>主题阅读不是连续读完最多的书，而是围绕一个问题比较多个来源，最终形成自己的判断。</p><h2 id="明确比较维度" tabindex="-1">明确比较维度 <a class="header-anchor" href="#明确比较维度" aria-label="Permalink to “明确比较维度”">​</a></h2><p>阅读前先列出需要回答的三到五个问题。每个来源都用同一组问题记录，便于发现一致结论与关键分歧。</p><h2 id="区分事实与观点" tabindex="-1">区分事实与观点 <a class="header-anchor" href="#区分事实与观点" aria-label="Permalink to “区分事实与观点”">​</a></h2><p>事实需要可追溯的证据，观点需要说明推理过程和适用边界。总结时不要把作者判断改写成无条件事实。</p><h2 id="用输出结束阅读" tabindex="-1">用输出结束阅读 <a class="header-anchor" href="#用输出结束阅读" aria-label="Permalink to “用输出结束阅读”">​</a></h2><p>一轮主题阅读应以文章、分享、决策记录或实践实验结束。没有输出的阅读很难暴露理解漏洞。</p>',8)])])}const m=e(d,[["render",n]]);export{p as __pageData,m as default};
